// Formata o evento recebido do backend e loga no console do n8n
const EVENT_LABELS = {
  ticket_closed: 'Ticket FECHADO',
  ticket_high_priority: 'Ticket com prioridade ALTA',
};

return $input.all().map(({ json }) => {
  const { event, ticket, changes, sent_at } = json.body;
  const message = `[Mini Inbox] ${EVENT_LABELS[event] ?? event}: #${ticket.id} "${ticket.subject}" (${ticket.customer_name})`;
  console.log(message);

  return {
    json: {
      message,
      event,
      ticket_id: ticket.id,
      customer: ticket.customer_name,
      status: ticket.status,
      priority: ticket.priority,
      changes,
      sent_at,
      processed_at: new Date().toISOString(),
    },
  };
});
